import sys
sys.setrecursionlimit(10000)

def build(tokens):
    root = [int(tokens[0]), None, None]
    q = [root]
    qi = 0
    p = 1
    while qi < len(q) and p < len(tokens):
        node = q[qi]
        qi += 1
        for side in (1, 2):
            if p >= len(tokens):
                break
            t = tokens[p]
            p += 1
            if t != 'null':
                c = [int(t), None, None]
                node[side] = c
                q.append(c)
    return root

def same(a, b):
    if a is None or b is None:
        return a is None and b is None
    return a[0] == b[0] and same(a[1], b[1]) and same(a[2], b[2])

def has(a, b):
    if a is None:
        return False
    return same(a, b) or has(a[1], b) or has(a[2], b)

lines = [ln for ln in sys.stdin.read().split('\n') if ln.strip()]
print('true' if has(build(lines[0].split()), build(lines[1].split())) else 'false')

