import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static boolean isSubtree(TreeNode root, TreeNode subRoot) {
        // Write your solution here
        return false;
    }

    static TreeNode build(String line) {
        String[] tk = line.trim().split("\\s+");
        if (tk.length == 0 || tk[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tk[0]));
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int p = 1;
        while (!queue.isEmpty() && p < tk.length) {
            TreeNode node = queue.poll();
            if (p < tk.length) {
                if (!tk[p].equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(tk[p]));
                    queue.add(node.left);
                }
                p++;
            }
            if (p < tk.length) {
                if (!tk[p].equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(tk[p]));
                    queue.add(node.right);
                }
                p++;
            }
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.trim().isEmpty()) lines.add(line);
        }
        TreeNode root = build(lines.get(0));
        TreeNode subRoot = build(lines.get(1));
        System.out.println(isSubtree(root, subRoot) ? "true" : "false");
    }
}
